additional_cases.source:
terraform { required_version = ">= 1.5" }
variable "instances" { default = 3 }
locals { names = [for i in range(var.instances) : "web-${i}" if i > 0] }
resource "aws_instance" "web" {
  count = var.instances
  ami = null
  tags = { Name = upper("web-${count.index}") }
  user_data = <<-EOT
#!/bin/bash
echo "${var.instances}"
EOT
}
